import 'package:aivexus_stable_unique/stable_unique.dart';
void main() {
  final original = <int>[3, 3, -1, 3, 2, -1, 0, 2, 0];
  final before = List<int>.from(original);
  final result = uniqueStable(original);
  if (result.toString() != '[3, -1, 2, 0]') throw StateError('stable distinct order failed: $result');
  if (original.toString() != before.toString()) throw StateError('input mutated');
  if (identical(result, original)) throw StateError('result is not a new list');
  if (uniqueStable(<int>[]).isNotEmpty) throw StateError('empty input failed');
  if (uniqueStable(<int>[5, 5, 5]).toString() != '[5]') throw StateError('duplicate removal failed');
  if (uniqueStable(<int>[-2, 7, -2, 7, 1]).toString() != '[-2, 7, 1]') throw StateError('negative number order failed');
  print('PASS: independent consumer of Qwen-generated stable-unique module');
}

import 'package:aivexus_delta_codec/delta_codec.dart';
void main() {
  final samples = <int>[12, -4, -4, 9, 0];
  final original = List<int>.from(samples);
  final encoded = encodeDeltas(samples);
  if (encoded.toString() != '[12, -16, 0, 13, -9]') throw StateError('encoding failed: $encoded');
  if (decodeDeltas(encoded).toString() != samples.toString()) throw StateError('decoding failed');
  if (samples.toString() != original.toString()) throw StateError('input mutated');
  if (encodeDeltas(<int>[]).isNotEmpty || decodeDeltas(<int>[]).isNotEmpty) throw StateError('empty input failed');
  print('PASS: independently consumed LLM-generated delta module');
}

import 'package:aivexus_integer_frequencies/integer_frequencies.dart';
void main() {
final data=<int>[3,-1,3,0,-1,3]; final before=List<int>.from(data); final r=countFrequencies(data); if(r.length!=3||r[3]!=3||r[-1]!=2||r[0]!=1) throw StateError('counts $r'); if(r.keys.toList().toString()!='[3, -1, 0]') throw StateError('order $r'); if(data.toString()!=before.toString()) throw StateError('mutated'); if(countFrequencies(<int>[]).isNotEmpty) throw StateError('empty');
print('PASS: independent Dart consumer for original model-generated integer_frequencies');
}

import 'package:aivexus_fixed_chunks/fixed_chunks.dart';
void main() {
final d=<int>[1,2,3,4,5]; final before=List<int>.from(d); if(chunkIntegers(d,2).toString()!='[[1, 2], [3, 4], [5]]') throw StateError('partition'); if(chunkIntegers(<int>[],3).isNotEmpty) throw StateError('empty'); if(chunkIntegers(<int>[-1,0],9).toString()!='[[-1, 0]]') throw StateError('large'); if(d.toString()!=before.toString()) throw StateError('mutated'); var rejected=false; try {chunkIntegers(d,0);} on ArgumentError {rejected=true;} if(!rejected) throw StateError('invalid size');
print('PASS: independent Dart consumer for original model-generated fixed_chunks');
}

import 'package:aivexus_cumulative_max/cumulative_max.dart';
void main() {
final d=<int>[-5,-8,2,1,7,7]; if(cumulativeMaximum(d).toString()!='[-5, -5, 2, 2, 7, 7]') throw StateError('prefix maximum'); if(cumulativeMaximum(<int>[]).isNotEmpty) throw StateError('empty'); if(d.toString()!='[-5, -8, 2, 1, 7, 7]') throw StateError('input');
print('PASS: independent Dart consumer for original model-generated cumulative_max');
}

import 'package:aivexus_first_subsequence/first_subsequence.dart';
void main() {
if(findSubsequence(<int>[2,3,2,3,4],<int>[2,3,4])!=2) throw StateError('first match'); if(findSubsequence(<int>[1,2,1,2],<int>[1,2])!=0) throw StateError('earliest'); if(findSubsequence(<int>[1,2],<int>[3])!=-1) throw StateError('missing'); if(findSubsequence(<int>[],<int>[])!=0) throw StateError('empty'); if(findSubsequence(<int>[1],<int>[1,2])!=-1) throw StateError('too long');
print('PASS: independent Dart consumer for original model-generated first_subsequence');
}

import 'package:aivexus_running_product/running_product.dart';
void main() {
final d=<int>[2,-3,4,0,9]; if(runningProducts(d).toString()!='[2, -6, -24, 0, 0]') throw StateError('products'); if(runningProducts(<int>[]).isNotEmpty) throw StateError('empty'); if(runningProducts(<int>[-2,-2]).toString()!='[-2, 4]') throw StateError('negatives'); if(d.length!=5) throw StateError('mutation');
print('PASS: independent Dart consumer for original model-generated running_product');
}

import 'package:aivexus_index_positions/index_positions.dart';
void main() {
final d=<int>[4,9,4,4,9]; final r=groupIndices(d); if(r.keys.toList().toString()!='[4, 9]') throw StateError('key order'); if(r[4].toString()!='[0, 2, 3]'||r[9].toString()!='[1, 4]') throw StateError('positions'); if(groupIndices(<int>[]).isNotEmpty) throw StateError('empty'); if(d.toString()!='[4, 9, 4, 4, 9]') throw StateError('mutated');
print('PASS: independent Dart consumer for original model-generated index_positions');
}

import 'package:aivexus_rotate_left/rotate_left.dart';
void main() {
final d=<int>[1,2,3,4]; if(rotateLeft(d,1).toString()!='[2, 3, 4, 1]') throw StateError('left'); if(rotateLeft(d,5).toString()!='[2, 3, 4, 1]') throw StateError('wrap'); if(rotateLeft(d,-1).toString()!='[4, 1, 2, 3]') throw StateError('right'); if(rotateLeft(<int>[],3).isNotEmpty) throw StateError('empty'); if(d.toString()!='[1, 2, 3, 4]') throw StateError('mutated');
print('PASS: independent Dart consumer for original model-generated rotate_left');
}

import 'package:aivexus_palindrome_filter/palindrome_filter.dart';
void main() {
final d=<String>['aba','abc','Aba','','aa','aba','z']; final r=filterPalindromes(d); if(r.toString()!='[aba, , aa, aba, z]') throw StateError('filter: $r'); if(filterPalindromes(<String>[]).isNotEmpty) throw StateError('empty input'); if(d.length!=7) throw StateError('mutation');
print('PASS: independent Dart consumer for original model-generated palindrome_filter');
}

import 'package:aivexus_adjacent_pairs/adjacent_pairs.dart';
void main() {
if(adjacentPairs(<int>[3,-1,0,0]).toString()!='[[3, -1], [-1, 0], [0, 0]]') throw StateError('pairs'); if(adjacentPairs(<int>[]).isNotEmpty) throw StateError('empty'); if(adjacentPairs(<int>[5]).isNotEmpty) throw StateError('singleton');
print('PASS: independent Dart consumer for original model-generated adjacent_pairs');
}

import 'package:aivexus_interleave_lists/interleave_lists.dart';
void main() {
final l=<int>[1,2,3], r=<int>[-1,-2]; if(interleaveIntegers(l,r).toString()!='[1, -1, 2, -2, 3]') throw StateError('interleave'); if(interleaveIntegers(<int>[],<int>[4,5]).toString()!='[4, 5]') throw StateError('left empty'); if(interleaveIntegers(<int>[],<int>[]).isNotEmpty) throw StateError('both empty'); if(l.toString()!='[1, 2, 3]'||r.toString()!='[-1, -2]') throw StateError('mutation');
print('PASS: independent Dart consumer for original model-generated interleave_lists');
}

import 'package:aivexus_intersection_unique/intersection_unique.dart';
void main() {
final first=<int>[3,-1,3,2,0,2], second=<int>[2,3,2,9]; if(intersectStable(first,second).toString()!='[3, 2]') throw StateError('intersection'); if(intersectStable(<int>[],second).isNotEmpty) throw StateError('empty'); if(intersectStable(<int>[-5,-5,0],<int>[-5]).toString()!='[-5]') throw StateError('duplicates'); if(first.length!=6) throw StateError('mutation');
print('PASS: independent Dart consumer for original model-generated intersection_unique');
}

import 'package:aivexus_count_in_range/count_in_range.dart';
void main() {
final d=<int>[-4,-1,0,2,2,9]; if(countInRange(d,-1,2)!=4) throw StateError('range'); if(countInRange(d,3,3)!=0) throw StateError('none'); if(countInRange(d,10,-10)!=0) throw StateError('reverse'); if(countInRange(<int>[],0,3)!=0) throw StateError('empty'); if(d.length!=6) throw StateError('mutated');
print('PASS: independent Dart consumer for original model-generated count_in_range');
}

import 'package:aivexus_max_run_length/max_run_length.dart';
void main() {
if(longestRunLength(<int>[1,1,2,2,2,3,3])!=3) throw StateError('longest'); if(longestRunLength(<int>[] )!=0) throw StateError('empty'); if(longestRunLength(<int>[-1,-1,-1,-1])!=4) throw StateError('all same'); if(longestRunLength(<int>[4,5,6])!=1) throw StateError('distinct');
print('PASS: independent Dart consumer for original model-generated max_run_length');
}
